"""Build a self-contained visual review from the original and repaired SVGs."""
import json,html,hashlib
from pathlib import Path
from icon_set.model.icons.registry import create
w=Path('icon_set/work/parallel-spacing-repair');rows=json.loads((w/'targets.json').read_text());notes=json.loads((w/'notes.json').read_text());results=json.loads((w/'results.json').read_text());cards=[]
for row in rows:
 name=row['icon_id'];before=(w/'before'/f'{name}.svg').read_text();after=create(name).to_svg()
 advisory=results[name]['internal']!='pass'
 cards.append(f'''<article data-name="{html.escape(name)}" data-advisory="{str(advisory).lower()}"><header><h2>{html.escape(name)}</h2><span class="badge">Pass</span></header><div class="pair"><figure><figcaption>Before</figcaption><div class="preview">{before}</div></figure><figure><figcaption>After</figcaption><div class="preview">{after}</div></figure></div><p>{html.escape(notes[name])}</p>{'<p class="advisory">Nonblocking review: tapered fins and curved body details.</p>' if advisory else ''}</article>''')
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>113 icon repairs · Before and after</title><style>
:root{font:15px/1.5 system-ui,sans-serif;color:#1c2822;background:#f4f5f1;--card:#fff;--line:#d9ded8;--muted:#657269;--ink:#17231c;--size:48px}*{box-sizing:border-box}body{margin:0;padding:36px;max-width:1600px;margin-inline:auto}h1{font-size:32px;letter-spacing:-1px;margin:0 0 8px}h2{font-size:14px;overflow-wrap:anywhere;margin:0}p{margin:10px 0;color:var(--muted)}.intro{max-width:850px}nav{display:flex;gap:16px;flex-wrap:wrap;padding:18px 0;position:sticky;top:0;background:inherit;z-index:2;align-items:center}input,select,button{font:inherit;border:1px solid var(--line);border-radius:7px;background:var(--card);color:inherit;padding:8px 12px}input[type=search]{min-width:270px}label{display:flex;gap:7px;align-items:center}main{display:grid;grid-template-columns:repeat(auto-fill,minmax(300px,1fr));gap:16px}article{background:var(--card);border:1px solid var(--line);border-radius:12px;padding:18px}article[hidden]{display:none}header{display:flex;align-items:center;justify-content:space-between;gap:12px}.badge{font-size:12px;background:#dcecdf;color:#285336;border-radius:20px;padding:3px 9px}.pair{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:20px}figure{margin:0}figcaption{text-align:center;color:var(--muted);font-size:12px}.preview{min-height:174px;display:grid;place-items:center;color:var(--ink)}.preview svg{width:var(--size);height:var(--size)}.advisory{color:#977022;font-size:13px}body.dark{--card:#202a24;--line:#3a493f;--muted:#b4c2b8;--ink:#fff;background:#162019;color:#eef4ef}footer{padding:26px 0;color:var(--muted);font-size:13px}
</style><body><h1>113 icon repairs</h1><p class="intro">Spacing repaired in the original Python models. Curves, repeated details and proportions reviewed at native size in light and dark themes. All 113 pass required validation, spacing, bounds and hole checks. One shark retains nonblocking advisories on tapered details.</p><nav><input id="search" type="search" placeholder="Find an icon" aria-label="Find an icon"><label>Size <select id="size"><option value="48px">48 px · native</option><option value="144px">144 px · enlarged</option></select></label><label><input id="dark" type="checkbox"> Dark theme</label><label><input id="advisory" type="checkbox"> Advisory only</label><span id="count">113 icons</span></nav><main>'''+''.join(cards)+'''</main><footer>Original icon IDs and source identities preserved. No new model variants. Profile dimensions, stroke width and validation tolerances unchanged. Automated passes are not human approval.</footer><script>
const cards=[...document.querySelectorAll('article')],search=document.querySelector('#search'),only=document.querySelector('#advisory');function filter(){let count=0;for(const card of cards){card.hidden=!card.dataset.name.includes(search.value.trim().toLowerCase())||(only.checked&&card.dataset.advisory!=='true');if(!card.hidden)count++}document.querySelector('#count').textContent=count+' icons'}search.addEventListener('input',filter);only.addEventListener('change',filter);document.querySelector('#size').addEventListener('change',e=>document.documentElement.style.setProperty('--size',e.target.value));document.querySelector('#dark').addEventListener('change',e=>document.body.classList.toggle('dark',e.target.checked));</script></body></html>'''
(w/'index.html').write_text(page)
print('Wrote visual comparison for',len(cards),'icons')
